/usr/bin/bash -lc "python3 -B - <<'PY'
from random import Random
from solution import occupancy

random = Random(42)
for _ in range(5000):
    start = random.randrange(-8, 8)
    end = random.randrange(start + 1, 10)
    events = [[random.randrange(-10, 11), random.randrange(-5, 6)] for _ in range(random.randrange(25))]
    original = [event[:] for event in events]
    values = [sum(delta for time, delta in events if time <= tick) for tick in range(start, end)]
    peak = max(values)
    expected = {\"area\": sum(values), \"peak\": peak, \"peak_at\": start + values.index(peak)}
    assert occupancy(events, start, end) == expected, (events, start, end, expected)
    assert events == original

span = 10**30
assert occupancy([[-span, -3], [0, 7], [0, -5], [span, 100]], -span, span) == {
    \"area\": -4 * span, \"peak\": -1, \"peak_at\": 0
}
assert occupancy([[0, 4]], 0, 0) == {\"area\": 0, \"peak\": None, \"peak_at\": None}
try:
    occupancy([], 1, 0)
except ValueError:
    pass
else:
    raise AssertionError(\"Expected ValueError for start > end\")
print(\"5,000 random cases and boundary checks passed\")
PY"

